export type PipelinePhase = 1 | 2 | 3 | 4 | 5 | 6 | 7

export type PipelineMode = 'ask' | 'auto'

export interface TranscriptWord {
  text: string
  start: number
  end: number
}

export interface Transcript {
  text: string
  words: TranscriptWord[]
  durationSec: number
}

export interface Concept {
  moment_id: string
  start: number
  end: number
  type: 'formula' | 'steps' | 'definition' | 'diagram' | 'comparison'
  topic: string
  excerpt: string
  manim_brief: string
}

export interface ManimClip {
  moment_id: string
  url: string
  durationSec: number
}

export type ExtractConceptsOutput =
  | {
      success: true
      cached?: boolean
      concepts: Concept[]
      awaitingApproval?: boolean
      message?: string
    }
  | { success: false; error: string }

export type RenderManimClipsOutput = {
  success: boolean
  clips: ManimClip[]
  failed: { moment_id: string; error: string }[]
  error?: string
}

export interface PipelineState {
  phase: PipelinePhase
  mode: PipelineMode
  videoUrl?: string
  completedPhases: number[]
  draftVideoUrl?: string
}
